function getSelectedImageUrls(img_selected, img_filter, img_source) {
    return img_selected
        .map(key => {
            const filteredImage = img_filter.find(item => item.key === key);

            if (!filteredImage) return null;

            const sourceImage = img_source.find(
                item => item.title === filteredImage.title
            );

            return sourceImage ? sourceImage.url : null;
        })
        .filter(Boolean);
}
